// Normalizes CRM order search results
const payload = $input.first().json.body || $input.first().json;
const params = payload.parameters || {};

// Sample normalized return matching registry
const demoOrders = [
  {
    order_id: 'ORD-0001',
    customer_id: 'CUST-001',
    customer_name: 'John Doe',
    customer_email: 'john@example.com',
    status: 'delayed',
    delay_days: 4,
    created_at: '2026-10-25T10:00:00Z'
  },
  {
    order_id: 'ORD-0002',
    customer_id: 'CUST-002',
    customer_name: 'Jane Smith',
    customer_email: 'jane.smith2@example.com',
    status: 'delayed',
    delay_days: 3,
    created_at: '2026-10-26T11:00:00Z'
  }
];

const filtered = demoOrders.filter(o => {
  if (params.status && o.status !== params.status) return false;
  if (params.delayed_more_than_days && o.delay_days < params.delayed_more_than_days) return false;
  return true;
});

return [{
  json: {
    success: true,
    provider_reference: 'crm_ref_' + Date.now(),
    orders: filtered,
    count: filtered.length,
    normalized_data: { orders: filtered, count: filtered.length }
  }
}];

const payload = $input.first().json.body || $input.first().json;
const params = payload.parameters || {};
const ticketId = 'TCK-' + Math.floor(1000 + Math.random() * 9000);

return [{
  json: {
    success: true,
    provider_reference: ticketId,
    ticket_id: ticketId,
    status: 'created',
    normalized_data: {
      ticket_id: ticketId,
      status: 'created',
      customer_id: params.customer_id,
      priority: params.priority
    }
  }
}];
